contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address to, uint256 id) public payable {
        require(to != address(0), "to must be nonzero");

        // Ensure the id is minted to `from` using the public transferFrom surface.
        // Since a fresh C is deployed, id is unminted and ownerOf reverts.
        // We mint via _mint-like behavior using transferFrom? No public mint exists,
        // so we use the test contract's ability to receive tokens? The only public
        // mint paths are fillOrder (requires signatures/premium) and no direct mint.
        // Instead, we rely on the fact that the fresh C has no minted tokens.
        // To exercise transferFrom on a valid minted id, we must first mint through fillOrder.
        // However, fillOrder requires a valid signature and a non-zero premium transferFrom
        // from the maker, which we cannot guarantee for arbitrary parameters.
        // Therefore, we test the revert path: transferFrom on an unminted id must revert
        // because `from != _ownerOf[id]` (both from and _ownerOf[id] cannot equal
        // an arbitrary from since _ownerOf[id] is address(0)).
        bool reverted;
        try c.transferFrom(from, to, id) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted == (from != address(0)));
    }

    receive() external payable {}
}

