contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address to, uint256 id, bytes calldata data) public {
        require(to != address(0), "to zero");

        // Mint the tested token id to `from` through the public mint path.
        // fillOrder mints both the order hash and the opposite order hash to msg.sender and order.maker.
        C.Order memory order;
        order.maker = from;
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(c);
        order.strike = 0;
        order.premium = 0;
        order.duration = 0;
        order.expiration = block.timestamp + 1 days;
        order.nonce = id;

        uint256[] memory floorIds = new uint256[](0);
        bytes memory sig;

        // This may revert if from is address(0); the interesting rule is about successful mints.
        try c.fillOrder(order, sig, floorIds) {
            // successful mint: owner of both the order hash and its opposite is set
            uint256 orderHashId = uint256(keccak256(abi.encode(order.isCall, order.isLong, order.baseAsset, order.strike, order.premium, order.duration, order.expiration, order.nonce)));

            // Use the minted token id as the tested id. We test the token minted to `from`.
            uint256 tokenId = orderHashId;

            address beforeOwner = c.ownerOf(tokenId);
            bool beforeAuth = beforeOwner == from || c.isApprovedForAll(from, address(this)) || c.getApproved(tokenId) == address(this);

            bool reverted;
            if (beforeOwner == from && !beforeAuth) {
                // Not authorized: must revert
                try c.safeTransferFrom(from, to, tokenId, data) { reverted = false; } catch { reverted = true; }
                assert(reverted);
            } else {
                // Authorized and minted: must succeed (or revert only if recipient rejects the safe transfer callback)
                try c.safeTransferFrom(from, to, tokenId, data) {
                    reverted = false;
                } catch {
                    reverted = true;
                }

                // The Putty override makes balanceOf(from) == max, so the safe transfer succeeds whenever
                // the token is minted and the caller is authorized, unless `to` is a contract that rejects.
                // We assert the authorization/mint condition matches non-revert when `to` is an EOA or empty.
                if (to.code.length == 0) {
                    assert(!reverted);
                }
            }
        } catch {
            // if fillOrder reverted, the test setup failed; no meaningful assert about safeTransferFrom
            assert(true);
        }
    }

    receive() external payable {}
}

